"use strict";

// Key EXPRESSION shapes, rather than element kinds. Each is a method key,
// because the method spelling is the one RWF-023 fixes; the point of the
// file is that the fix routes the key through the call graph's ORDINARY
// expression traversal rather than pattern-matching a bare `key()` call,
// so every one of these resolves with no shape-specific rule.
//
// The conditional class and the direct imported member call live in their
// own modules (`conditional.js`, `direct-call.js`) so that each is scanned
// in isolation -- with them here, the search finds a shorter path and the
// evidence never demonstrates the shape the file is named for.
const danger = require("./danger");

const flag = process.env.FIXTURE_LIB_FLAG === "on";

function key() {
  danger.explode("wrapper");
  return "x";
}

// A parenthesized key -- the same expression with one more node in the way.
class Parenthesized {
  [(key())]() {}
}

// A call nested inside another call.
class Nested {
  [String(key())]() {}
}

// A sequence expression: the key's VALUE is "x", but key() still runs.
class Sequence {
  [(key(), "x")]() {}
}

// A template literal: the key runs in the substitution.
class Template {
  [`x${key()}`]() {}
}

// Short-circuiting forms. key() is the LEFT operand of `||` so it always
// runs; in `&&` and `?:` it runs only on some loads -- which is still
// reachable, because reachability is MAY-execute.
class LogicalOr {
  [key() || "x"]() {}
}
class LogicalAnd {
  [flag && key()]() {}
}
class Conditional {
  [flag ? key() : "x"]() {}
}

// A class EXPRESSION, evaluated by the variable statement that holds it.
const ClassExpression = class {
  [key()]() {}
};

// A class expression nested inside an object literal, which is itself
// evaluated during module evaluation.
const holder = {
  Inner: class {
    [key()]() {}
  },
};

module.exports = {
  Parenthesized,
  Nested,
  Sequence,
  Template,
  LogicalOr,
  LogicalAnd,
  Conditional,
  ClassExpression,
  holder,
};
